 async function checkDpadSlide(style,orientation){
  await phone.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));
  const boxes={};for(const id of ['up','down','left','right'])boxes[id]=await phone.locator('[data-control=dpad-'+id+']').boundingBox();
  const at=(b,id=90)=>({x:b.x+b.width/2,y:b.y+b.height/2,id}),center={x:(at(boxes.up).x+at(boxes.down).x)/2,y:(at(boxes.up).y+at(boxes.down).y)/2,id:90},attack=at(await phone.locator('[data-control=face0]').boundingBox(),91);
  const state=async()=>(await api('/api/admin/status')).players[0].state;
  async function expectButtons(buttons){await until(async()=>{const s=await state();return JSON.stringify([...s.buttons].sort())===JSON.stringify([...buttons].sort())&&s.lx===0&&s.ly===0&&s.rx===0&&s.ry===0&&s.lt===0&&s.rt===0;},'slide input '+buttons.join('+')+' '+orientation);}
  let finger=at(boxes.down);await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[finger,attack]});await expectButtons(['down','a']);
  for(const direction of [null,'up','right','left','down']){finger=direction?at(boxes[direction]):center;await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[finger,attack]});await expectButtons(direction?[direction,'a']:['a']);const pressed=await phone.locator('.dpad-control.pressed').evaluateAll(nodes=>nodes.map(el=>el.dataset.mapping));assert.deepEqual(pressed,direction?[direction]:[]);}
  finger=at(await phone.locator('[data-control=face1]').boundingBox());await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[finger,attack]});await expectButtons(['a']);assert.equal(await phone.locator('.dpad-control.pressed').count(),0);
  finger=at(boxes.up);await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[finger,attack]});await expectButtons(['up','a']);await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[finger]});await expectButtons(['a']);assert.equal(await phone.locator('.dpad-control.pressed').count(),0);await cdp.send('Input.dispatchTouchEvent',{type:'touchCancel',touchPoints:[]});await expectButtons([]);
  if(style==='joined'){await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[center]});await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[at(boxes.right)]});await expectButtons(['right']);await cdp.send('Input.dispatchTouchEvent',{type:'touchCancel',touchPoints:[]});await expectButtons([]);assert.equal(await phone.locator('.dpad-control.pressed').count(),0);}
  const index=sentStates.length;await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[at(boxes.down)]});await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[at(boxes.up)]});await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await until(()=>{const frames=sentStates.slice(index),down=frames.findIndex(s=>s.buttons.includes('down')),up=frames.findIndex((s,i)=>i>down&&s.buttons.includes('up')&&!s.buttons.includes('down'));return down>=0&&up>down&&frames.slice(up+1).some(s=>!s.buttons.length);},'fast D-pad slide preserves changes');
  pass('D-pad slide '+style+' '+orientation+': continuous four directions, neutral center/outside, re-entry, independent attack, release/cancel/highlights, fast gesture preserves frames');
 }
 async function checkDpadOptions(){
  const up=await phone.locator('[data-control=dpad-up]').boundingBox(),at=b=>({x:b.x+b.width/2,y:b.y+b.height/2,id:92});
  async function configure(enabled,mapping){await phone.locator('#edit').click();await phone.locator('#control').selectOption('dpad-up');await phone.locator('#enabled').setChecked(enabled);await phone.locator('#mapping').selectOption(mapping);await phone.locator('#save').click();await phone.locator('#editor').waitFor({state:'hidden'});}
  async function expect(buttons){await until(async()=>{const s=(await api('/api/admin/status')).players[0].state;return JSON.stringify([...s.buttons].sort())===JSON.stringify([...buttons].sort())&&s.lx===0&&s.ly===0;},'D-pad disabled/remapped input');}
  async function slideUp(){const down=await phone.locator('[data-control=dpad-down]').boundingBox();await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[at(down)]});await expect(['down']);await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[at(up)]});}
  await configure(false,'up');await slideUp();await expect([]);await cdp.send('Input.dispatchTouchEvent',{type:'touchCancel',touchPoints:[]});await configure(true,'rb');await slideUp();await expect(['rb']);await cdp.send('Input.dispatchTouchEvent',{type:'touchCancel',touchPoints:[]});await expect([]);await configure(true,'up');
  const down=at(await phone.locator('[data-control=dpad-down]').boundingBox()),second={...down,id:93},right=at(await phone.locator('[data-control=dpad-right]').boundingBox());await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[at(up),second]});await expect(['up','down']);await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[right,second]});await expect(['right','down']);await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[right]});await expect(['down']);assert.equal(await phone.locator('[data-control=dpad-down]').evaluate(el=>el.classList.contains('pressed')),true);assert.equal(await phone.locator('[data-control=dpad-right]').evaluate(el=>el.classList.contains('pressed')),false);await cdp.send('Input.dispatchTouchEvent',{type:'touchCancel',touchPoints:[]});await expect([]);
  pass('D-pad sliding respects disabled directions and remapping; two fingers keep independent input and highlights');
 }
