  for(const id of ['size','deadZone','sensitivity','opacity']){const input=phone.locator('#'+id),original=await input.evaluate(el=>({value:+el.value,min:+el.min,max:+el.max}));const high=await dragRange(id,.85);let large;if(id==='size'){await showPreview();large=await phone.locator('[data-control=stick]').boundingBox();}const low=await dragRange(id,.15);assert.ok(high>low,orientation+' '+id+' drags both ways: '+JSON.stringify({high,low,box:await input.boundingBox(),scroll:await phone.locator('#controller-content').evaluate(el=>el.scrollTop)}));if(id==='size'){await showPreview();const small=await phone.locator('[data-control=stick]').boundingBox();assert.ok(large.width>small.width+10,'size changes visible control');}await dragRange(id,(original.value-original.min)/(original.max-original.min));}
