   const stage=await phone.locator('#stage').boundingBox(),home=await phone.locator('[data-control=stick]').boundingBox(),face=await phone.locator('[data-control=face0]').boundingBox(),portrait=await phone.evaluate(()=>matchMedia('(orientation:portrait)').matches);
   const logical=(x,y,id)=>portrait?{x:stage.x+stage.width-y,y:stage.y+x,id}:{x:stage.x+x,y:stage.y+y,id};
